import{_ as r,a0 as i,w as l,s as d,I as n,x as o,a1 as s,A as a,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"安卓編年史（31）：安卓 6.0 棉花糖 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（31）：安卓 6.0 棉花糖 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（31）：安卓 6.0 棉花糖 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（31）：安卓 6.0 棉花糖 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/31 The (updated) history of Android","title":"安卓編年史（31）：安卓 6.0 棉花糖","tag":"The history of Android","desc":""},"relativePath":"The history of Android/31 The (updated) history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/31 The (updated) history of Android.md"};function g(m,t,T,w,f,h){const p=i("Link");return l(),d("div",null,[t[28]||(t[28]=n("h1",{id:"安卓編年史-31-安卓-6-0-棉花糖",tabindex:"-1"},[o("安卓編年史（31）：安卓 6.0 棉花糖 "),n("a",{class:"header-anchor",href:"#安卓編年史-31-安卓-6-0-棉花糖","aria-label":"Permalink to “安卓編年史（31）：安卓 6.0 棉花糖”"},"​")],-1)),t[29]||(t[29]=n("h3",{id:"安卓-6-0-棉花糖",tabindex:"-1"},[o("安卓 6.0 棉花糖 "),n("a",{class:"header-anchor",href:"#安卓-6-0-棉花糖","aria-label":"Permalink to “安卓 6.0 棉花糖”"},"​")],-1)),n("p",null,[t[1]||(t[1]=o("2015 年 10 月，谷歌給世界帶來了安卓 6.0 棉花糖。配合這個版本的發佈，谷歌委託生產了兩部新的 Nexus 設備：",-1)),s(p,{href:"http://arstechnica.com/gadgets/2015/10/nexus-5x-and-nexus-6p-review-the-true-flagships-of-the-android-ecosystem/"},{default:a(()=>[...t[0]||(t[0]=[o("華為 Nexus 6P 和 LG Nexus 5X",-1)])]),_:1}),t[2]||(t[2]=o("。除了常規的性能升級，新手機還帶有一套關鍵硬件：為棉花糖的新指紋 API 準備的指紋識別器。棉花糖還引入了一個瘋狂的全新搜索特性，被稱作“Google Now on Tap”，用户控制的應用權限，一個全新的數據備份系統，以及許多其它的改良。",-1))]),t[30]||(t[30]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/32-1-1440x1466.jpg",alt:""})],-1)),t[31]||(t[31]=n("h4",{id:"新谷歌應用",tabindex:"-1"},[o("新谷歌應用 "),n("a",{class:"header-anchor",href:"#新谷歌應用","aria-label":"Permalink to “新谷歌應用”"},"​")],-1)),n("p",null,[t[4]||(t[4]=o("棉花糖是",-1)),s(p,{href:"http://arstechnica.com/gadgets/2015/09/google-gets-a-new-logo/"},{default:a(()=>[...t[3]||(t[3]=[o("谷歌大標誌重新設計",-1)])]),_:1}),t[5]||(t[5]=o("後的第一個安卓版本。系統也隨之升級，主要是一個新的谷歌應用，給搜索小部件，搜索頁面以及應用圖標添加了一個多彩的標誌。",-1))]),t[32]||(t[32]=e('<p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/app-drawer.jpg" alt=""></p><p>谷歌將應用抽屜從頁面導航的橫向佈局還原回了單頁豎直滾動表的形式。早期版本的安卓用的都是豎直滾動表的形式，直到谷歌在蜂巢中改成了橫向頁面系統。滾動單頁面讓人更容易從很多應用中找到目標。一項“快速滾動”的特性同樣好用，它可以讓你拖動滾動條來激活字母索引。新的應用抽屜佈局也用到了小部件抽屜上。考慮到舊系統中小部件輕鬆就超過了 15 頁，這是個大改進。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/2015-10-01-19.01.201.png" alt=""></p><p>棉花糖應用抽屜頂部的“建議應用”欄也讓查找應用變得更快。該欄顯示的內容一直在變化，試圖在你需要的時候為你提供你需要的應用。它使用了算法來統計應用使用，經常一起打開的應用以及每天的打開次數。</p><h4 id="google-now-on-tap——一個沒有完美實現的特性" tabindex="-1">Google Now on Tap——一個沒有完美實現的特性 <a class="header-anchor" href="#google-now-on-tap——一個沒有完美實現的特性" aria-label="Permalink to “Google Now on Tap——一個沒有完美實現的特性”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/ontap.jpg" alt=""></p><p>棉花糖的頭等新特性之一就是“Google Now on Tap”。有了 Now on Tap，你可以在安卓的任意界面長按 home 鍵，安卓會將整個屏幕發送給谷歌進行處理。谷歌會試着分析頁面上的內容，並從屏幕底部彈出顯示一個特殊的搜索結果列表。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/onta3p.jpg" alt=""></p><p>Now on Tap 產生的結果不是通常的 10 個藍色鏈接——即便那必定有一個通往谷歌搜索的鏈接。Now on Tap 還可以深度連接到其它使用了谷歌的應用索引功能的應用。他們的想法是你可以在 Youtube 音樂視頻那裏喚出 Now on tap，然後獲得一個到谷歌 Play 或亞馬遜“購買”頁面的鏈接。在演員新聞文章處喚出 Now on Tap 可以鏈接到 IMDb 應用中該演員的頁面上。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/assist-api-980x576.jpg" alt=""></p><p>谷歌沒有讓這成為私有特性，而是給安卓創建了一個全新的“Assistant API（助理 API）”。用户可以挑選一個“助理應用”，它可以在長按 home 鍵的時候獲取很多信息。助理應用會獲取所有由當前應用加載的數據——不僅是直接從屏幕獲取到的——連同所有這些圖片還有任何開發者想要包含的元數據。這個 API 驅動了谷歌 Now on Tap，如果願意的話，它還允許第三方打造 Now on Tap 的競爭對手。</p><p>谷歌在棉花糖的發佈會上炒作了 Now on Tap，但實際上，這項特性不是很實用。谷歌搜索的價值在於你可以問它準確的問題——你輸入你想要的內容，它搜索整個互聯網尋找答案或網頁。Now on Tap 讓事情變得無限困難，因為它甚至不知道你要問的是什麼。你帶着特定意圖打開了 Now on Tap，但你發送給谷歌的查詢是很不準確的“屏幕上的所有內容”。谷歌需要猜測你查詢的內容然後試着基於它給出有用的結果或操作。</p>',12)),n("p",null,[t[7]||(t[7]=o("在這背後，谷歌可能在瘋狂處理整個頁面文字和圖片來強行獲得你想要的結果。但往往 Now on Tap 給出的結果像是頁面每個合適的名詞的搜索結果列表。從結果列表中篩選多個查詢就像是陷入必應的“",-1)),s(p,{href:"https://www.youtube.com/watch?v=9yfMVbaehOE"},{default:a(()=>[...t[6]||(t[6]=[o("搜索結果過載",-1)])]),_:1}),t[8]||(t[8]=o("”廣告裏那樣的情形。查詢目標的缺失讓 Now on Tap 感覺像是讓谷歌給你讀心，而它永遠做不到。谷歌最終給文本選中菜單打了補丁，添加了一個“助理”按鈕，給 Now on Tap 提供一些它極度需要的搜索目標。",-1))]),t[33]||(t[33]=e('<p>不得不説 Now on Tap 是個失敗的產物。Now on Tap 的快捷方式——長按 home 鍵——基本上讓它成為了一個隱藏，難以發現的特性，很容易就被遺忘了。我們推測這個特性的使用率非常低。即便用户發現了 Now on Tap，它經常沒法讀取你的想法，在幾次嘗試之後，大多數用户可能會選擇放棄。</p><p>隨着 2016 年 Google Pixels 的發佈，谷歌似乎承認了失敗。它把 Now on Tap 改名成了“屏幕搜索”並把它降級成了谷歌助手的支援。谷歌助理——谷歌的新語音命令系統——接管了 Now on Tap 的 home 鍵手勢並將它關聯到了語音系統激活後的二次手勢。谷歌似乎還從 Now on Tap 差勁的可發現性中學到了教訓。谷歌給助理給 home 鍵添加了一組帶動畫的彩點，幫助用户發現並記住這個特性。</p><h4 id="權限" tabindex="-1">權限 <a class="header-anchor" href="#權限" aria-label="Permalink to “權限”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/33-1-1440x1454.jpg" alt=""></p><p>安卓 6.0 終於引入了應用權限系統，讓用户可以細粒度地控制應用可以訪問的數據。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/perm.jpg" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/denied-1.jpg" alt=""></p><p>應用在安裝的時候不再給你一份長長的權限列表。在棉花糖中，應用安裝根本不詢問任何權限。當應用需要一個權限的時候——比如訪問你的位置、攝像頭、麥克風，或聯繫人列表的時候——它們會在需要用到的時候詢問。在你使用應用的時候，如果需要新權限時會彈出一個“允許或拒絕”的對話框。一些應用的設置流程這麼處理：在啓動的時候詢問獲取一些關鍵權限，其它的等到需要用到的時候再彈出提示。這樣更好地與用户溝通了需要權限是為了做什麼——應用需要攝像頭權限，因為你剛剛點擊了攝像頭按鈕。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/apps.jpg" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/system-permisions.jpg" alt=""></p><p>除了及時的“允許或拒絕”對話框，棉花糖還添加了一個權限設置界面。這個複選框大列表讓數據敏感用户可以瀏覽應用擁有的權限。他們不僅可以通過應用來查詢，也可以通過權限來查詢。舉個例子，你可以查看所有擁有訪問麥克風權限的應用。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/warning.jpg" alt=""></p>',12)),n("p",null,[t[10]||(t[10]=o("谷歌試驗應用權限已經有一段時間了，這些設置界面基本就是隱藏的“",-1)),s(p,{href:"http://www.androidpolice.com/2013/07/25/app-ops-android-4-3s-hidden-app-permission-manager-control-permissions-for-individual-apps/"},{default:a(()=>[...t[9]||(t[9]=[o("App Ops",-1)])]),_:1}),t[11]||(t[11]=o("”系統的重生，它是在安卓 4.3 中不小心引入並很快被移除的權限管理系統。",-1))]),t[34]||(t[34]=e('<p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/Google_IO_2015_-_Android_M_Permissions_-_YouTube_-_Google_Chrome_2015-09-04_12-31-49.jpg" alt=""></p><p>儘管谷歌在之前版本就試驗過了，棉花糖的權限系統最大的不同是它代表了一個向權限系統的有序過渡。安卓 4.3 的 App Ops 從沒有計劃暴露給用户，所以開發者不瞭解它。在 4.3 中拒絕一個應用需要的一個權限經常導致奇怪的錯誤信息或一個徹底的崩潰。棉花糖的系統對開發者是缺省的——新的權限系統只適用於針對棉花糖 SDK 開發的應用，谷歌將它作為開發者已經為權限處理做好準備的信號。權限系統還允許在一項功能由於權限被拒絕無法正常工作時與用户進行溝通。應用會被告知它們的權限請求被拒絕，它們可以指導用户在需要該功能的時候去打開該權限訪問。</p><h4 id="指紋-api" tabindex="-1">指紋 API <a class="header-anchor" href="#指紋-api" aria-label="Permalink to “指紋 API”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/finger1.jpg" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/fingerlock.jpg" alt=""></p>',5)),n("p",null,[t[13]||(t[13]=o("在棉花糖出現之前，少數廠商推出了他們自己的指紋解決方案以作為對",-1)),s(p,{href:"http://arstechnica.com/apple/2014/09/ios-8-thoroughly-reviewed/10/#h3"},{default:a(()=>[...t[12]||(t[12]=[o("蘋果的 Touch ID",-1)])]),_:1}),t[14]||(t[14]=o(" 的回應。但在棉花糖中，谷歌終於帶來了生態級別的指紋識別 API。新系統包含了指紋註冊界面，指紋驗證鎖屏以及允許應用將內容保護在一個指紋掃描或鎖屏驗證之後的 API。",-1))]),t[35]||(t[35]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/10/fingerprintplaystore.jpg",alt:""})],-1)),t[36]||(t[36]=n("p",null,"Play 商店是最先支持該 API 的應用之一。你可以使用你的指紋來購買應用，而不用輸入你的密碼。Nexus 5X 和 6P 是最先支持指紋 API 的手機，手機背面帶有指紋讀取硬件。",-1)),t[37]||(t[37]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/09/2015-09-04_16-38-31.png",alt:""})],-1)),t[38]||(t[38]=n("p",null,"指紋 API 推出不久後時間，是罕見的安卓生態合作例子之一。所有帶有指紋識別的手機都使用谷歌的 API，並且大多數銀行和購物應用都很好地支持了它。",-1)),t[39]||(t[39]=n("hr",null,null,-1)),t[40]||(t[40]=n("p",null,"作者簡介：",-1)),t[41]||(t[41]=n("p",null,"Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),t[42]||(t[42]=n("hr",null,null,-1)),n("p",null,[t[16]||(t[16]=o("via: ",-1)),s(p,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/31/"},{default:a(()=>[...t[15]||(t[15]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/31/",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=o("作者：",-1)),s(p,{href:"http://arstechnica.com/author/ronamadeo"},{default:a(()=>[...t[17]||(t[17]=[o("RON AMADEO",-1)])]),_:1}),t[21]||(t[21]=o(" 譯者：",-1)),s(p,{href:"https://github.com/alim0x"},{default:a(()=>[...t[18]||(t[18]=[o("alim0x",-1)])]),_:1}),t[22]||(t[22]=o(" 校對：",-1)),s(p,{href:"https://github.com/wxy"},{default:a(()=>[...t[19]||(t[19]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[25]||(t[25]=o("本文由 ",-1)),s(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[23]||(t[23]=[o("LCTT",-1)])]),_:1}),t[26]||(t[26]=o(" 原創編譯，",-1)),s(p,{href:"https://linux.cn/"},{default:a(()=>[...t[24]||(t[24]=[o("Linux中國",-1)])]),_:1}),t[27]||(t[27]=o(" 榮譽推出",-1))])])}const x=r(u,[["render",g]]);export{P as __pageData,x as default};
